                ds.getProperty(DataSelection.PROP_USESTIMEDRIVER);
            if ((dtimes != null) && (dtimes.size() > 0)
                    && (ud1 != null)) {
                this.usesTimeDriver = ((Boolean) ud1).booleanValue();
            }
        }
    }
}


